{"title":"Animate gravity moves with a playful bounce","files":[{"path":"TTT.js","operation":"write","content":"const boardEl = document.querySelector(".game-board");
const sizeSelect = document.querySelector("#board-size");
const statusEl = document.querySelector("#status");
const matchupEl = document.querySelector("#matchup");
const resetButton = document.querySelector("#reset");
const coin = document.querySelector("#coin");

let size = 3;
let board = [];
let cells = [];
let winLines = [];
let humanMark = "X";
let computerMark = "O";
let currentPlayer = "X";
let gameOver = false;
let turnToken = 0;
let cancelToss = null;
let cancelDrop = null;
let dropping = false;

resetButton.addEventListener("click", startGame);
sizeSelect.addEventListener("change", startGame);
startGame();

function makeWinLines(n) {
    const length = n === 5 ? 4 : 3;
    const directions = [[0, 1], [1, 0], [1, 1], [1, -1]];
    const lines = [];
    for (let row = 0; row < n; row++) {
        for (let column = 0; column < n; column++) {
            for (const [dr, dc] of directions) {
                const endRow = row + (length - 1) * dr;
                const endColumn = column + (length - 1) * dc;
                if (endRow < 0 || endRow >= n || endColumn < 0 || endColumn >= n) {
                    continue;
                }
                lines.push(Array.from({ length }, (_, i) => (row + i * dr) * n + column + i * dc));
            }
        }
    }
    return lines;
}

// Return the landing cell for a click, or null when that move is unavailable.
function landingCell(index) {
    if (!Number.isInteger(index) || index < 0 || index >= board.length) return null;
    if (size === 3) return board[index] ? null : index;
    const column = index % size;
    for (let row = size - 1; row >= 0; row--) {
        const candidate = row * size + column;
        if (!board[candidate]) return candidate;
    }
    return null;
}

// One landing cell per column on gravity boards, every empty cell on 3×3.
function legalMoves() {
    if (size === 3) {
        return board.flatMap((mark, index) => mark ? [] : [index]);
    }
    return Array.from({ length: size }, (_, column) => landingCell(column))
        .filter((index) => index !== null);
}

function updateCellLabel(index) {
    const cell = cells[index];
    const content = board[index] || "empty";
    if (size === 3) {
        cell.setAttribute("aria-label", `${cell.dataset.label}, ${content}`);
        return;
    }
    const landing = landingCell(index);
    const action = landing === null
        ? "column full"
        : `drop in column ${index % size + 1}, lands in row ${Math.floor(landing / size) + 1}`;
    cell.setAttribute("aria-label", `${cell.dataset.label}, ${content}; ${action}`);
}

function buildBoard() {
    boardEl.replaceChildren();
    boardEl.style.setProperty("--board-size", size);
    boardEl.setAttribute("aria-label", `${size} by ${size} tic-tac-toe board`);
    cells = board.map((_, index) => {
        const cell = document.createElement("button");
        const row = Math.floor(index / size) + 1;
        const column = index % size + 1;
        cell.type = "button";
        cell.className = "cell";
        cell.dataset.label = `Row ${row}, column ${column}`;
        cell.disabled = true;
        cell.addEventListener("click", () => playHumanMove(index));
        boardEl.appendChild(cell);
        return cell;
    });
    cells.forEach((_, index) => updateCellLabel(index));
}

function startGame() {
    const token = ++turnToken;
    if (cancelToss) cancelToss();
    if (cancelDrop) cancelDrop();
    const selectedSize = Number(sizeSelect.value);
    size = [3, 4, 5].includes(selectedSize) ? selectedSize : 3;
    board = Array(size * size).fill(null);
    winLines = makeWinLines(size);
    gameOver = false;
    buildBoard();
    matchupEl.textContent = "";
    statusEl.textContent = "Tossing a coin…";

    const side = Math.random() < 0.5 ? "heads" : "tails";
    playToss(side).then(() => {
        if (token !== turnToken) return;
        humanMark = side === "heads" ? "X" : "O";
        computerMark = humanMark === "X" ? "O" : "X";
        currentPlayer = "X";
        matchupEl.textContent = side === "heads"
            ? "Heads. You start as X."
            : "Tails. Computer starts as X.";

        if (currentPlayer === humanMark) {
            statusEl.textContent = "Your turn";
            unlockEmptyCells();
        } else {
            statusEl.textContent = "Computer's turn";
            window.setTimeout(() => computerTurn(token), 450);
        }
    });
}

function playToss(side) {
    coin.classList.remove("land-heads", "land-tails", "show-heads", "show-tails");
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        coin.classList.add(`show-${side}`);
        return Promise.resolve();
    }

    return new Promise((resolve) => {
        let timer;
        const finish = () => {
            window.clearTimeout(timer);
            coin.removeEventListener("animationend", onEnd);
            cancelToss = null;
            resolve();
        };
        const onEnd = (event) => {
            if (event.target === coin) finish();
        };
        cancelToss = finish;
        coin.addEventListener("animationend", onEnd);
        void coin.offsetWidth;
        coin.classList.add(`land-${side}`);
        timer = window.setTimeout(() => {
            coin.classList.remove("land-heads", "land-tails");
            coin.classList.add(`show-${side}`);
            finish();
        }, 1500);
    });
}

function playHumanMove(index) {
    if (gameOver || dropping || currentPlayer !== humanMark) return;
    const landing = landingCell(index);
    if (landing === null) return;
    const token = turnToken;
    makeMove(landing, humanMark, token, () => {
        currentPlayer = computerMark;
        statusEl.textContent = "Computer's turn";
        lockBoard();
        window.setTimeout(() => computerTurn(token), 450);
    });
}

function computerTurn(token) {
    if (token !== turnToken || gameOver || dropping || currentPlayer !== computerMark) return;
    const index = chooseComputerMove();
    if (index === undefined) return;
    makeMove(index, computerMark, token, () => {
        currentPlayer = humanMark;
        statusEl.textContent = "Your turn";
        unlockEmptyCells();
    });
}

// Keep the real board unchanged until the visual mark settles.
function makeMove(index, mark, token, afterLanding) {
    if (size === 3 || window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        if (placeMark(index, mark)) afterLanding();
        return;
    }
    dropping = true;
    lockBoard();
    statusEl.textContent = mark === humanMark ? "Your mark is falling…" : "Computer's mark is falling…";

    // Anchor the overlay to the target grid cell so resizing keeps it aligned.
    const visual = document.createElement("span");
    visual.className = `falling-mark ${mark.toLowerCase()}`;
    visual.setAttribute("aria-hidden", "true");
    visual.textContent = mark;
    visual.style.gridColumn = String(index % size + 1);
    visual.style.gridRow = String(Math.floor(index / size) + 1);
    const targetRect = cells[index].getBoundingClientRect();
    const topRect = cells[index % size].getBoundingClientRect();
    visual.style.setProperty("--drop-distance", `${targetRect.top - topRect.top + topRect.height}px`);
    boardEl.appendChild(visual);

    let finished = false;
    let timer;
    const cleanup = () => {
        if (finished) return false;
        finished = true;
        window.clearTimeout(timer);
        visual.removeEventListener("animationend", onAnimation);
        visual.removeEventListener("animationcancel", onAnimation);
        visual.remove();
        cancelDrop = null;
        dropping = false;
        return true;
    };
    const finish = () => {
        if (!cleanup() || token !== turnToken) return;
        if (placeMark(index, mark)) afterLanding();
    };
    const onAnimation = (event) => {
        if (event.target === visual && event.animationName === "drop-mark") finish();
    };
    cancelDrop = cleanup;
    visual.addEventListener("animationend", onAnimation);
    visual.addEventListener("animationcancel", onAnimation);
    // Recover when animations or animation events are unavailable.
    timer = window.setTimeout(finish, 800);
}

function placeMark(index, mark) {
    board[index] = mark;
    const cell = cells[index];
    cell.textContent = mark;
    cell.classList.add(mark.toLowerCase());
    cells.forEach((_, i) => updateCellLabel(i));

    const line = findWinningLine(mark);
    if (line) {
        gameOver = true;
        line.forEach((i) => cells[i].classList.add("win"));
        statusEl.textContent = mark === humanMark ? "You win" : "Computer wins";
        lockBoard();
        return false;
    }
    if (board.every(Boolean)) {
        gameOver = true;
        statusEl.textContent = "Draw";
        lockBoard();
        return false;
    }
    return true;
}

function chooseComputerMove() {
    let bestScore = -Infinity;
    const choices = [];
    for (const index of legalMoves()) {
        board[index] = computerMark;
        const score = minimax(humanMark, 1, -Infinity, Infinity);
        board[index] = null;
        if (score > bestScore) {
            bestScore = score;
            choices.length = 0;
            choices.push(index);
        } else if (score === bestScore) {
            choices.push(index);
        }
    }
    return choices[Math.floor(Math.random() * choices.length)];
}

function minimax(player, depth, alpha, beta) {
    if (findWinningLine(computerMark)) return 10000 - depth;
    if (findWinningLine(humanMark)) return depth - 10000;
    if (board.every(Boolean)) return 0;
    // Search all of 3×3; cap larger boards to keep turns responsive.
    if ((size === 4 && depth >= 4) || (size === 5 && depth >= 3)) {
        return evaluateBoard();
    }

    const maximizing = player === computerMark;
    let best = maximizing ? -Infinity : Infinity;
    for (const index of legalMoves()) {
        board[index] = player;
        const score = minimax(opponent(player), depth + 1, alpha, beta);
        board[index] = null;
        if (maximizing) {
            best = Math.max(best, score);
            alpha = Math.max(alpha, best);
        } else {
            best = Math.min(best, score);
            beta = Math.min(beta, best);
        }
        if (beta <= alpha) break;
    }
    return best;
}

function evaluateBoard() {
    const weights = [0, 1, 6, 30, 150, 0];
    return winLines.reduce((score, line) => {
        let computer = 0;
        let human = 0;
        line.forEach((index) => {
            if (board[index] === computerMark) computer++;
            if (board[index] === humanMark) human++;
        });
        if (computer && human) return score;
        return score + weights[computer] - weights[human];
    }, 0);
}

function findWinningLine(player) {
    return winLines.find((line) => line.every((index) => board[index] === player)) ?? null;
}

function opponent(mark) {
    return mark === "X" ? "O" : "X";
}

function lockBoard() {
    cells.forEach((cell) => {
        cell.disabled = true;
    });
}

function unlockEmptyCells() {
    cells.forEach((cell, index) => {
        cell.disabled = landingCell(index) === null;
    });
}
"},{"path":"TTT.css","operation":"write","content":"*,
*::before,
*::after {
    box-sizing: border-box;
}

body {
    margin: 0;
    min-height: 100vh;
    display: grid;
    place-items: center;
    font-family: "Segoe UI", system-ui, sans-serif;
    background: #1b2430;
    color: #f4f7fb;
}

.container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1.5rem;
    padding: 1.5rem 0;
}

h1 {
    margin: 0;
    font-size: 2rem;
    font-weight: 600;
    letter-spacing: 0.04em;
}

.size-control {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

#board-size {
    padding: 0.4rem 0.6rem;
    border: 1px solid #7e91a8;
    border-radius: 6px;
    background: #243044;
    color: #f4f7fb;
    font: inherit;
}

#size-help {
    margin: -1rem 0 0;
    color: #c5d0de;
    font-size: 0.875rem;
    text-align: center;
}

.coin-stage {
    width: 4.5rem;
    height: 4.5rem;
    perspective: 600px;
}

.coin {
    position: relative;
    width: 100%;
    height: 100%;
    transform-style: preserve-3d;
}

.face {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    border-radius: 50%;
    background: radial-gradient(circle at 35% 35%, #ffe7a3, #e2b34a 55%, #a97820);
    box-shadow: inset 0 0 0 4px #c9922e;
    color: #3a2a08;
    font-size: 1.75rem;
    font-weight: 800;
    backface-visibility: hidden;
}

.face.tails {
    transform: rotateY(180deg);
    background: radial-gradient(circle at 35% 35%, #f3f6fb, #c5cedb 55%, #7d8b9e);
    box-shadow: inset 0 0 0 4px #9aa6b5;
}

.coin.land-heads {
    animation: toss-heads 1.1s cubic-bezier(0.2, 0.7, 0.2, 1) forwards;
}

.coin.land-tails {
    animation: toss-tails 1.1s cubic-bezier(0.2, 0.7, 0.2, 1) forwards;
}

.coin.show-heads { transform: rotateY(0deg); }
.coin.show-tails { transform: rotateY(180deg); }

@keyframes toss-heads {
    0% { transform: rotateY(0) translateY(0); }
    40% { transform: rotateY(720deg) translateY(-28px); }
    100% { transform: rotateY(1800deg) translateY(0); }
}

@keyframes toss-tails {
    0% { transform: rotateY(0) translateY(0); }
    40% { transform: rotateY(720deg) translateY(-28px); }
    100% { transform: rotateY(1980deg) translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
    .coin.land-heads,
    .coin.land-tails {
        animation: none;
    }
}

#matchup,
#status {
    margin: 0;
    min-height: 1.5rem;
    text-align: center;
}

#matchup {
    font-size: 1.05rem;
    color: #c5d0de;
}

#status { font-size: 1.25rem; }

#reset {
    border: none;
    border-radius: 999px;
    padding: 0.6rem 1.25rem;
    background: #3d7eff;
    color: #f4f7fb;
    font: inherit;
    font-weight: 600;
    cursor: pointer;
}

#reset:hover { background: #5b92ff; }

#reset:focus-visible,
#board-size:focus-visible,
.cell:focus-visible {
    outline: 3px solid #7eb6ff;
    outline-offset: 2px;
}

.game-board {
    --board-size: 3;
    display: grid;
    grid-template-columns: repeat(var(--board-size), minmax(0, 1fr));
    grid-template-rows: repeat(var(--board-size), minmax(0, 1fr));
    width: min(90vw, 360px);
    aspect-ratio: 1;
    gap: clamp(4px, 2vw, 10px);
    padding: clamp(4px, 2vw, 10px);
    background: #0f1720;
    border-radius: 16px;
}

.cell {
    min-width: 0;
    margin: 0;
    padding: 0;
    border: none;
    border-radius: 10px;
    background: #243044;
    color: #f4f7fb;
    font: inherit;
    font-size: clamp(1.5rem, 10vw, 3.5rem);
    font-weight: 700;
    line-height: 1;
    cursor: pointer;
}

.cell:hover { background: #2d3d56; }
.cell:disabled { cursor: default; }
.cell:disabled:hover { background: #243044; }
.cell.x { color: #7eb6ff; }
.cell.o { color: #f2b56b; }
.cell.win,
.cell.win:disabled:hover { background: #355a3a; }

.falling-mark {
    z-index: 1;
    display: grid;
    place-items: center;
    min-width: 0;
    pointer-events: none;
    font: inherit;
    font-size: clamp(1.5rem, 10vw, 3.5rem);
    font-weight: 700;
    line-height: 1;
    animation: drop-mark 550ms linear both;
}

.falling-mark.x { color: #7eb6ff; }
.falling-mark.o { color: #f2b56b; }

@keyframes drop-mark {
    0% { transform: translateY(calc(-1 * var(--drop-distance))); animation-timing-function: cubic-bezier(0.5, 0, 1, 1); }
    65% { transform: translateY(0); animation-timing-function: ease-out; }
    78% { transform: translateY(-14px); animation-timing-function: ease-in; }
    89% { transform: translateY(0); animation-timing-function: ease-out; }
    95% { transform: translateY(-4px); animation-timing-function: ease-in; }
    100% { transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
    .falling-mark { animation: none; }
}
"},{"path":"README.md","operation":"write","content":"# Tic-Tac-Toe

A browser-based game against the computer, using plain HTML, CSS and JavaScript. Open `TTT.html` in a browser to play; no build or dependencies are required.

Choose a 3×3, 4×4 or 5×5 board. The default is 3×3. Changing the size immediately discards the current game and starts a new one; **New game** keeps the selected size. A coin toss determines who starts, and X always plays first.

On 3×3, choose an empty cell. On 4×4 and 5×5, select any cell in a column, including an occupied cell: the mark lands in that column's lowest empty row. Full columns cannot be selected. The computer follows the same gravity rule. Both players' marks fall and bounce into place; the board stays locked until the mark settles. With reduced motion enabled, marks appear immediately. Resetting or changing size cancels a drop.

Win with three consecutive marks on 3×3 or 4×4, or four consecutive marks on 5×5. Lines can appear anywhere horizontally, vertically or diagonally. A full board without a winner is a draw. The computer uses the same winning rules, with full minimax on 3×3 and a depth-limited search on 4×4 and 5×5, so its play on larger boards is not guaranteed to be perfect.

These are single-board variants, not Ultimate Tic Tac Toe.

## Tests

With Node.js installed, run `node --test tests/game.test.js tests/gravity.test.js tests/animation.test.js`. The tests use only Node's built-in modules; the game itself does not require Node.js. They mock the DOM; visual animation and assistive-technology behavior should also be checked in a browser.
"},{"path":"tests/animation.test.js","operation":"write","content":"const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const root = path.join(__dirname, '..');
const source = fs.readFileSync(path.join(root, 'TTT.js'), 'utf8');

class Element {
    constructor() {
        this.children = [];
        this.listeners = {};
        this.attributes = {};
        this.dataset = {};
        this.styles = {};
        this.style = { setProperty: (name, value) => { this.styles[name] = value; } };
        this.textContent = '';
        this.value = '';
        this.disabled = false;
        const classes = new Set();
        this.classList = {
            add: (...names) => names.forEach((name) => classes.add(name)),
            remove: (...names) => names.forEach((name) => classes.delete(name)),
            contains: (name) => classes.has(name)
        };
    }
    setAttribute(name, value) { this.attributes[name] = value; }
    addEventListener(name, fn) { (this.listeners[name] ??= []).push(fn); }
    removeEventListener(name, fn) { this.listeners[name] = (this.listeners[name] || []).filter((item) => item !== fn); }
    dispatch(name, details = {}) { for (const fn of [...(this.listeners[name] || [])]) fn({ target: this, ...details }); }
    click() { if (!this.disabled) this.dispatch('click'); }
    appendChild(child) { child.parent = this; this.children.push(child); }
    replaceChildren() { this.children.forEach((child) => { child.parent = null; }); this.children = []; }
    remove() { if (this.parent) { this.parent.children = this.parent.children.filter((child) => child !== this); this.parent = null; } }
    getBoundingClientRect() {
        const index = this.parent.children.indexOf(this);
        const n = Number(this.parent.styles['--board-size']);
        return { top: Math.floor(index / n) * 100, height: 90 };
    }
}

function setup(random = 0, reduced = false) {
    const elements = Object.fromEntries(['.game-board', '#board-size', '#status', '#matchup', '#reset', '#coin'].map((key) => [key, new Element()]));
    elements['#board-size'].value = '3';
    const timers = new Map();
    let nextTimer = 0;
    const math = Object.create(Math);
    math.random = () => random;
    const context = vm.createContext({
        document: { querySelector: (name) => elements[name], createElement: () => new Element() },
        window: {
            matchMedia: () => ({ matches: reduced }),
            setTimeout: (fn, delay) => { const id = ++nextTimer; timers.set(id, { fn, delay }); return id; },
            clearTimeout: (id) => timers.delete(id)
        },
        Math: math
    });
    vm.runInContext(source, context);
    return {
        elements,
        run: (code) => vm.runInContext(code, context),
        runDelay(delay) {
            const entry = [...timers].find(([, timer]) => timer.delay === delay);
            assert.ok(entry, `missing ${delay}ms timer`);
            timers.delete(entry[0]);
            entry[1].fn();
        },
        timerCount: () => timers.size
    };
}

async function select(game, n, reduced = false) {
    game.elements['#board-size'].value = String(n);
    game.elements['#board-size'].dispatch('change');
    if (!reduced) game.elements['#coin'].dispatch('animationend');
    await Promise.resolve();
}

function finish(visual, event = 'animationend') {
    visual.dispatch(event, { animationName: 'drop-mark' });
}

test('human and computer gravity moves wait for the drop and lock the board', async () => {
    for (const n of [4, 5]) {
        const game = setup();
        await select(game, n);
        const board = game.elements['.game-board'];
        const cells = [...board.children];
        const target = (n - 1) * n + 1;
        cells[1].click();
        const visual = board.children.at(-1);
        assert.equal(visual.className, 'falling-mark x');
        assert.equal(visual.attributes['aria-hidden'], 'true');
        assert.equal(visual.style.gridColumn, '2');
        assert.equal(visual.style.gridRow, String(n));
        assert.equal(visual.styles['--drop-distance'], `${(n - 1) * 100 + 90}px`);
        assert.equal(cells[target].textContent, '');
        assert.equal(game.run('board.filter(Boolean).length'), 0);
        assert.ok(cells.every((cell) => cell.disabled));
        game.run('playHumanMove(2)');
        assert.equal(game.run('board.filter(Boolean).length'), 0);
        visual.dispatch('animationend', { animationName: 'other' });
        assert.equal(cells[target].textContent, '');
        finish(visual);
        assert.equal(cells[target].textContent, 'X');
        assert.equal(game.elements['#status'].textContent, "Computer's turn");
        game.runDelay(450);
        const computerVisual = board.children.at(-1);
        assert.equal(computerVisual.className, 'falling-mark o');
        assert.equal(game.run('board.filter(Boolean).length'), 1);
        assert.ok(cells.every((cell) => cell.disabled));
        finish(computerVisual);
        assert.equal(game.run('board.filter(Boolean).length'), 2);
        assert.equal(game.elements['#status'].textContent, 'Your turn');
        assert.ok(cells.some((cell) => !cell.disabled));
    }
});

test('a shorter drop targets the actual landing row and wins are deferred', async () => {
    for (const n of [4, 5]) {
        const game = setup();
        await select(game, n);
        const board = game.elements['.game-board'];
        const cells = [...board.children];
        const length = n === 5 ? 4 : 3;
        const bottom = (n - 1) * n;
        game.run(`for (let i = 0; i < ${length - 1}; i++) placeMark(${bottom} + i, 'X'); unlockEmptyCells()`);
        cells[length - 1].click();
        const visual = board.children.at(-1);
        assert.notEqual(game.elements['#status'].textContent, 'You win');
        assert.ok(cells.every((cell) => !cell.classList.contains('win')));
        finish(visual);
        assert.equal(game.elements['#status'].textContent, 'You win');
        assert.ok(cells[bottom + length - 1].classList.contains('win'));
        assert.equal(game.timerCount(), 0);

        await select(game, n);
        const fresh = game.elements['.game-board'];
        const freshCells = [...fresh.children];
        game.run(`placeMark(${bottom}, 'O'); unlockEmptyCells()`);
        freshCells[bottom].click();
        const higher = fresh.children.at(-1);
        assert.equal(higher.style.gridRow, String(n - 1));
        assert.equal(higher.styles['--drop-distance'], `${(n - 2) * 100 + 90}px`);
        finish(higher);
        assert.equal(freshCells[bottom - n].textContent, 'X');
    }
});

test('draw is announced only after the final animated landing', async () => {
    const game = setup();
    await select(game, 5);
    const marks = ['XXOOX', 'OOXXO', 'XXOOX', 'OOXXO', 'XXOOX'].join('').split('');
    game.run(`board = ${JSON.stringify(marks)}; board[4] = null; unlockEmptyCells()`);
    const board = game.elements['.game-board'];
    board.children[4].click();
    const visual = board.children.at(-1);
    assert.notEqual(game.elements['#status'].textContent, 'Draw');
    finish(visual);
    assert.equal(game.elements['#status'].textContent, 'Draw');
    assert.equal(game.timerCount(), 0);
});

test('reset and size changes cancel drops and stale callbacks cannot modify the new game', async () => {
    for (const changeSize of [false, true]) {
        const game = setup();
        await select(game, 4);
        const board = game.elements['.game-board'];
        board.children[0].click();
        const visual = board.children.at(-1);
        const stale = [...visual.listeners.animationend];
        if (changeSize) {
            game.elements['#board-size'].value = '5';
            game.elements['#board-size'].dispatch('change');
        } else {
            game.elements['#reset'].dispatch('click');
        }
        assert.equal(visual.parent, null);
        stale.forEach((fn) => fn({ target: visual, animationName: 'drop-mark' }));
        game.elements['#coin'].dispatch('animationend');
        await Promise.resolve();
        assert.equal(game.run('board.filter(Boolean).length'), 0);
        assert.equal(game.elements['#status'].textContent, 'Your turn');
        assert.equal(board.children.length, changeSize ? 25 : 16);
        assert.equal(game.timerCount(), 0);
    }
});

test('animation cancellation and fallback timer finish only once', async () => {
    for (const mode of ['cancel', 'timer']) {
        const game = setup();
        await select(game, 4);
        const board = game.elements['.game-board'];
        board.children[0].click();
        const visual = board.children.at(-1);
        if (mode === 'cancel') finish(visual, 'animationcancel');
        else game.runDelay(800);
        finish(visual);
        assert.equal(game.run('board.filter(Boolean).length'), 1);
        assert.equal(game.elements['#status'].textContent, "Computer's turn");
        assert.equal(game.timerCount(), 1);
    }
});

test('reduced motion and 3×3 place marks immediately', async () => {
    const reduced = setup(0, true);
    await select(reduced, 5, true);
    const board = reduced.elements['.game-board'];
    board.children[0].click();
    assert.equal(board.children.length, 25);
    assert.equal(board.children[20].textContent, 'X');
    assert.equal(reduced.elements['#status'].textContent, "Computer's turn");
    reduced.runDelay(450);
    assert.equal(reduced.run('board.filter(Boolean).length'), 2);
    assert.equal(reduced.elements['#status'].textContent, 'Your turn');

    const normal = setup();
    normal.elements['#coin'].dispatch('animationend');
    await Promise.resolve();
    const small = normal.elements['.game-board'];
    small.children[0].click();
    assert.equal(small.children.length, 9);
    assert.equal(small.children[0].textContent, 'X');
});

test('stylesheet supplies a bouncing, reduced-motion-aware drop', () => {
    const css = fs.readFileSync(path.join(root, 'TTT.css'), 'utf8');
    assert.match(css, /animation:\s*drop-mark\s+550ms/);
    assert.match(css, /@keyframes\s+drop-mark/);
    assert.match(css, /translateY\(-14px\)/);
    assert.match(css, /prefers-reduced-motion:\s*reduce[^}]*\.falling-mark\s*\{\s*animation:\s*none/s);
});
